const message = String($json.chatInput ?? '').trim();
const lower = message.toLowerCase();

let route = 'collector';

if (/\b(cancel|cancellation|cancelled|remove my appointment)\b/.test(lower)) {
  route = 'cancellation';
} else if (/\b(book|booking|schedule|appointment|reserve|confirm my appointment)\b/.test(lower)) {
  route = 'booking';
}

let roleInstructions = '';

if (route === 'booking') {
  roleInstructions = `ROLE: BOOKING AGENT
Help the user complete a doctor appointment booking request.

Required fields:
1. patient name
2. phone number
3. hospital
4. doctor
5. appointment date
6. appointment time

Use the conversation history to reuse information already provided.
Ask only for missing information, preferably one or two fields at a time.
When all six fields are available, summarize them clearly and say:
"Booking request collected successfully. Phase 1 is a demo, so no real hospital booking has been made."
Never claim that a real appointment was booked or that a slot is available.`;
} else if (route === 'cancellation') {
  roleInstructions = `ROLE: CANCELLATION AGENT
Help the user cancel an existing doctor appointment.

Ask for enough information to identify the appointment:
- patient name
- phone number
- hospital
- doctor
- appointment date
- appointment time

Use conversation history when available.
When the details are sufficient, summarize the appointment and say:
"Cancellation request collected successfully. Phase 1 is a demo, so no real hospital appointment was cancelled."
Never claim that a real cancellation happened.`;
} else {
  roleInstructions = `ROLE: COLLECTOR AGENT
Understand whether the user wants to book or cancel an appointment.
If the user wants to book, collect:
- patient name
- phone number
- hospital
- doctor
- appointment date
- appointment time

If the user wants to cancel, collect the details needed to identify the appointment:
- patient name
- phone number
- hospital
- doctor
- appointment date
- appointment time

Ask naturally and do not ask again for information already present in the conversation history.
If the user's intention is unclear, ask whether they want to book or cancel.`;
}

return [{
  json: {
    ...$json,
    route,
    roleInstructions
  }
}];
